// ===== CONFIGURATION =====
const BOT_TOKEN = 'YOUR_BOT_TOKEN_HERE';
const CHANNEL_ID = '@SmartHomeIL_deals';
// =========================

// Load products from Fetch Products node
const data = $('Fetch Products').item.json;
if (!data || !data.products || data.products.length === 0) {
  throw new Error('Failed to load products. Check the products URL.');
}
const products = data.products;

// Load active promo (gracefully handle errors or missing file)
let promoData = null;
try {
  const raw = $input.item.json;
  if (raw && raw.active === true && raw.validUntil && Array.isArray(raw.codes)) {
    promoData = raw;
  }
} catch(e) {}

// Rotation tracking via workflow static data
const staticData = $getWorkflowStaticData('global');
if (typeof staticData.currentIndex !== 'number') {
  staticData.currentIndex = 0;
}
if (!staticData.weeklyProducts) {
  staticData.weeklyProducts = [];
}

// Pick next product (sequential rotation)
const product = products[staticData.currentIndex % products.length];
staticData.currentIndex = (staticData.currentIndex + 1) % products.length;

// Track for weekly digest
staticData.weeklyProducts.push({
  name: product.name,
  hebrewName: product.hebrewName,
  priceDisplay: product.priceDisplay,
  buyLink: product.buyLink
});

const haLabels = { full: 'נתמך מלא ✅', partial: 'נתמך חלקית ⚠️', none: 'לא נתמך ❌' };
const catEmoji = { switches: '💡', 'ac-controllers': '❄️', sensors: '📡', hubs: '🔌', vacuums: '🧹', plugs: '🔌', cameras: '📷', lighting: '💡', covers: '🪟', climate: '🌡️', controllers: '🎮' };
const emoji = catEmoji[product.category] || '📦';

// Build promo section if active and not expired
let promoSection = '';
const today = new Date().toISOString().split('T')[0];
if (promoData && promoData.active && promoData.validUntil >= today && promoData.codes.length > 0) {
  const topCodes = promoData.codes.slice(0, 3);
  const codeLines = topCodes.map(c => `🏷️ <code>${c.code}</code> — חסכון ${c.savings} על ${c.minSpend}+`).join('\n');
  promoSection = `\n\n🔥 <b>${promoData.saleName}</b> | עד ${promoData.discount}% הנחה\n${codeLines}\n⏰ בתוקף עד ${promoData.validUntil}`;
}

const text = `🏠 <b>דיל בית חכם!</b>\n\n${emoji} <b>${product.name}</b> - ${product.hebrewName}\n💰 <b>${product.priceDisplay}</b>\n⚡ מאומת 220V ישראלי ✅\n🔌 פרוטוקול: ${product.protocol}\n🏡 Home Assistant: ${haLabels[product.homeAssistantSupport]}\n⭐ דירוג: ${product.rating}/5\n\n✨ ${product.description}${promoSection}\n\n🛒 <a href="${product.buyLink}">לרכישה ←</a>\n📖 <a href="${product.websiteLink}">למדריך המלא באתר</a>\n\n#בית_חכם #220V #SmartHomeIL`;

return [{ json: { botToken: BOT_TOKEN, channelId: CHANNEL_ID, text } }];

