if (weeklyProducts.length === 0) return [];
const productsList = weeklyProducts.map((p, i) => `${i + 1}. <b>${p.name}</b> - ${p.hebrewName} (${p.priceDisplay})`).join('
');
const text = `📋 <b>סיכום שבועי — בית חכם IL</b>

השבוע סקרנו ${weeklyProducts.length} מוצרים מעולים:

${productsList}

🌐 <a href="${WEBSITE_URL}">לכל ההשוואות והמדריכים באתר</a>

